import{_ as t,o as s,c as r,a3 as a}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Vérification de compatibilité HA 2026.11","description":"Vérifications confirmées, tests locaux et problèmes ouverts des extensions UGSo sous Home Assistant 2026.11.","frontmatter":{"title":"Vérification de compatibilité HA 2026.11","description":"Vérifications confirmées, tests locaux et problèmes ouverts des extensions UGSo sous Home Assistant 2026.11."},"headers":[],"relativePath":"fr/collection/ha-2026-11-compatibility.md","filePath":"fr/collection/ha-2026-11-compatibility.md","lastUpdated":1794573073000}'),i={name:"fr/collection/ha-2026-11-compatibility.md"};function n(o,e,l,d,c,u){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="verification-de-compatibilite-ha-2026-11" tabindex="-1">Vérification de compatibilité HA 2026.11 <a class="header-anchor" href="#verification-de-compatibilite-ha-2026-11" aria-label="Permalink to &quot;Vérification de compatibilité HA 2026.11&quot;">​</a></h1><p><strong>État au 05/11/2026 · Core 2026.11.0 · Frontend 20261028.4 · Système de test .177 (port 80).</strong></p><p>Cette synthèse distingue les vérifications réelles, les confirmations de l’utilisateur et les tests locaux. Elle ne certifie pas toutes les fonctions ni toutes les variantes matérielles. La vérification initiale n’a modifié aucune version logicielle ; le correctif ultérieur de la barre latérale est documenté séparément ci-dessous.</p><h2 id="atlas-et-plugins" tabindex="-1">ATLAS et plugins <a class="header-anchor" href="#atlas-et-plugins" aria-label="Permalink to &quot;ATLAS et plugins&quot;">​</a></h2><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Paquet</th><th>Résultat et périmètre</th></tr></thead><tbody><tr><td>App ATLAS <strong>0.1.334</strong>, Card Editor <strong>0.2.0-alpha.115</strong></td><td>En conditions réelles : Ingress, hub avec six plugins actifs, éditeur, connexion HA avec 35 entités réelles et liste des projets existants chargés. Les 431 tests du paquet HA, 74 tests app/frontend et contrôles TypeScript des onze paquets du workspace ont réussi.</td></tr><tr><td>File Studio <strong>0.1.52</strong></td><td>En conditions réelles : arborescence, interface d’édition et chemins autorisés chargés. Quatre tests de paquet et validation du catalogue réussis. Aucun fichier existant modifié.</td></tr><tr><td>Automation Exporter / Editor <strong>0.1.28</strong></td><td>En conditions réelles : fichier système des automatisations lu après sa propre sauvegarde ; aucune automatisation préexistante. Neuf tests locaux réussis. Aucune écriture dans les fichiers système HA.</td></tr><tr><td>Terminal <strong>0.1.10</strong></td><td>Interface vérifiée en conditions réelles. <strong>L’utilisateur confirme le 05/11/2026 : ATLAS Terminal fonctionne.</strong> Cette confirmation complète le contrôle initial de l’interface ; elle ne valide pas séparément toutes les cibles SSH ni tous les thèmes Oh My Posh.</td></tr><tr><td>Bibliothèque d’icônes <strong>0.1.9</strong></td><td>En conditions réelles : 7 447 icônes MDI (7.4.47) chargées, recherche fonctionnelle. Dix tests et validation du paquet réussis.</td></tr><tr><td>Icon Studio <strong>0.1.17</strong></td><td>En conditions réelles : collection, aperçu SVG et interface de dessin chargés. Quinze tests et validation du paquet réussis ; collection existante inchangée.</td></tr></tbody></table></div><p>Le paquet de l’app ATLAS passe aussi la vérification sans écriture de 523 fichiers. Le test Python isolé du contrat de l’intégration HA n’a pas pu être exécuté localement, Home Assistant n’étant pas importable ; Docker n’était pas démarré. Un nouveau cycle complet d’écriture/restauration/HACS des projets ne fait pas partie de cette vérification.</p><h2 id="autres-extensions-ha" tabindex="-1">Autres extensions HA <a class="header-anchor" href="#autres-extensions-ha" aria-label="Permalink to &quot;Autres extensions HA&quot;">​</a></h2><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Paquet</th><th>Résultat et limite</th></tr></thead><tbody><tr><td><a href="/fr/collection/dashboard-layout-card-v2/">Dashboard Layout Card V2 <strong>0.1.181</strong></a></td><td>Test réel distinct réussi : ajout/modification de cartes dans la deuxième section, bouton d’ajout flottant, en-tête/pied de page et rechargement complet.</td></tr><tr><td><a href="/fr/projects/automation-status-card/">Automation Status Card <strong>0.1.3</strong></a></td><td>Tests réels réussis : affichage, activation/désactivation confirmée par HA, exécution en cours, lecture des traces, fin normale, cases à cocher, tout sélectionner/désélectionner et rechargement. Exemples individuels Bubble/Mushroom affichés. Vingt et un tests locaux réussis. Les erreurs et alertes de durée n’ont pas été provoquées à nouveau sous 2026.11.</td></tr><tr><td><a href="/fr/projects/sidebar-manager/">Sidebar Manager <strong>0.1.9</strong></a></td><td>Mise à jour de 0.1.7 vers <strong>0.1.9</strong> sur .177. Tests réels réussis : couleurs du texte/des icônes des entrées et groupes dans le dialogue natif, opacité, annulation, enregistrement, réinitialisation au thème et rechargement complet. Les 72 tests locaux réussissent. Objets de test supprimés ; disposition exportée identique à la sauvegarde initiale.</td></tr><tr><td><a href="/fr/projects/sidebar-colors/">Sidebar Colors <strong>0.1.1</strong></a></td><td><strong>0.1.1</strong> corrige le même sélecteur de lignes. Les 27 tests locaux réussissent, y compris les régressions DOM des anciens/nouveaux éléments HA et l’enregistrement/annulation. Aucune installation parallèle supplémentaire sur .177.</td></tr><tr><td><a href="/fr/projects/dashboard-user-manager/">Gestion des utilisateurs <strong>0.1.11</strong></a></td><td>En conditions réelles : 19 vues et quatre utilisateurs chargés, aucune modification enregistrée. <strong>Ouvert : avertissement de chargement supplémentaire pour l’ancien tableau de bord <code>lovelace</code>.</strong> Cause non définitivement établie. Trente-trois tests Python et dix-neuf tests Node de l’app réussis.</td></tr><tr><td><a href="/fr/projects/grafik-visual-studio/">HA Grafik Visual Studio <strong>0.1.296</strong></a></td><td>109 tests Python et 388 tests Node réussis. Aucun test réel dédié sur .177, où l’app n’est pas installée.</td></tr><tr><td><a href="/fr/projects/blocks-for-ha/">Blocks for HA <strong>0.1.66</strong></a></td><td>Dix tests Python et 172 tests Node réussis ; sept tests facultatifs ignorés. Aucun test réel sur .177.</td></tr><tr><td><a href="/fr/projects/mqtt-client/">Client MQTT <strong>0.1.17</strong></a></td><td>Trente-six tests Python réussis ; deux tests nécessitant un broker MQTT distinct ignorés. Aucun nouveau test réel avec un broker externe.</td></tr><tr><td><a href="/fr/projects/callmebot/">CallMeBot Whatsapp <strong>0.1.6</strong></a> / <a href="/fr/projects/callmebot-signal/">Signal <strong>0.1.2</strong></a></td><td>17/18 tests Python et trois tests d’identifiant de requête par app réussis. Aucun message envoyé à de vrais destinataires.</td></tr><tr><td>Tabbed Card V2 / Editor <strong>0.1.7</strong>, intégration HA <strong>0.1.3</strong></td><td>Syntaxe JavaScript/Python vérifiée ; aucune validation réelle de l’extension non installée.</td></tr><tr><td><a href="/fr/projects/fritzbox-to-mqtt/">FRITZ!Box to MQTT <strong>0.1.41</strong></a> / <a href="/fr/projects/heizoel-to-mqtt/">Fioul to MQTT <strong>0.1.15</strong></a></td><td>Syntaxe Python vérifiée ; appareils, source de données et découverte MQTT non testés en conditions réelles.</td></tr><tr><td>Paquet de widgets Materialdesign / <a href="/fr/projects/ultimate-timer/">Ultimate Timer Blueprint</a></td><td>Inclus dans l’inventaire ; aucun nouveau test fonctionnel réel complet.</td></tr></tbody></table></div><h2 id="problemes-connus-et-prochaines-verifications" tabindex="-1">Problèmes connus et prochaines vérifications <a class="header-anchor" href="#problemes-connus-et-prochaines-verifications" aria-label="Permalink to &quot;Problèmes connus et prochaines vérifications&quot;">​</a></h2><p><strong>Corrigé dans Sidebar Manager 0.1.9 et Sidebar Colors 0.1.1 :</strong> les couleurs prennent en charge l’ancien <code>ha-md-list-item</code> et le nouveau <code>ha-list-item-button</code>. Manager testé sur .177 : couleurs du texte/des icônes des entrées et groupes, opacité, annulation, enregistrement, réinitialisation au thème et rechargement complet. Les 72 tests Manager et 27 tests Colors réussissent. Colors testé séparément en local, sans chargement parallèle sur .177. Aucune migration des couleurs enregistrées nécessaire.</p><p>L’avertissement <code>lovelace</code> de la gestion des utilisateurs nécessite une investigation distincte. Une lecture échouée ne doit toujours pas être considérée comme un tableau de bord vide. Cet avertissement n’est pas encore attribué avec certitude à une régression de 2026.11.</p><p>Les apps non installées et les cycles d’écriture, de restauration, d’appareils ou de brokers non exécutés nécessitent d’autres tests réels. Les projets tiers comme UIX, Calendar Card Pro, Zendure et Frosted Glass n’ont pas été entièrement audités ici.</p><h2 id="sauvegarde-et-nettoyage" tabindex="-1">Sauvegarde et nettoyage <a class="header-anchor" href="#sauvegarde-et-nettoyage" aria-label="Permalink to &quot;Sauvegarde et nettoyage&quot;">​</a></h2><p>Une nouvelle sauvegarde complète a précédé la vérification. L’automatisation de test n’exécutait qu’un délai, sans déclencheur automatique ni action sur des appareils. Elle et son tableau de bord ont été supprimés ; paramètres, projets, plugins existants et « Test für APP » sont conservés. Après autorisation explicite de supprimer la plus ancienne sauvegarde, exactement trois sauvegardes complètes restent disponibles ; sauvegardes de mise à jour d’app et copies PC conservées.</p><h2 id="references" tabindex="-1">Références <a class="header-anchor" href="#references" aria-label="Permalink to &quot;Références&quot;">​</a></h2><ul><li><a href="https://www.home-assistant.io/blog/2026/11/04/release-202611/" target="_blank" rel="noreferrer">Changements officiels de HA 2026.11</a></li><li><a href="https://contributors.home-assistant.io/blog/2026/10/28/frontend-component-updates-2026.11/" target="_blank" rel="noreferrer">Composants du frontend en 2026.11</a></li><li><a href="https://contributors.home-assistant.io/blog/2026/10/23/config-entry-methods-return-none/" target="_blank" rel="noreferrer">Retours des config entries : booléens toujours acceptés pour les intégrations personnalisées</a></li><li><a href="https://github.com/home-assistant/frontend/blob/20261028.4/src/components/ha-items-display-editor.ts" target="_blank" rel="noreferrer">Éditeur d’affichage original 20261028.4</a></li></ul>',16)])])}const m=t(i,[["render",n]]);export{g as __pageData,m as default};
